        if tx > px:
            dx = 1
        elif tx < px:
            dx = -1
        if ty > py:
            dy = 1
        elif ty < py:
            dy = -1
        return dx, dy

    def is_blocked(nx, ny):
        if nx < 0 or nx >= gw or ny < 0 or ny >= gh:
            return True
        if (nx, ny) in obstacles:
            return True
        return False

    def try_move(dx, dy):
        nx, ny = px + dx, py + dy
        if not is_blocked(nx, ny):
            return [dx, dy]
        return None

