            if move:
                return move
        return [0, 0]

    # Prioritize resource collection
    resource_moves = []
    for rx, ry in resources:
        dx, dy = move_towards(rx, ry)
        move = try_move(dx, dy)
        if move:
            resource_moves.append((abs(rx - px) + abs(ry - py), move))
    if resource_moves:
        _, best_move = min(resource_moves, key=lambda x: x[0])
        return best_move

    # Defensive: move towards opponent
    dx, dy = move_towards(ox, oy)
    move = try_move(dx, dy)
    if move:
        return move

    # Fallback: try all directions
    for ddx, ddy in [(-1,0), (1,0), (0,-1), (0,1)]:
        move = try_move(ddx, ddy)
        if move:
            return move

    # Stay still if no move possible
    return [0, 0]

